//! Live compute-path parity vs Python (phase 5b): the frozen-seed
//! fixture generated by the REAL Python find_similar, replayed through
//! `compute_find_similar` and compared field-by-field. The same
//! fixture drives the extension-level pytest (the real PyO3 boundary).

use std::path::Path;

use cine_rec_db::Db;
use cine_rec_service::similar::{compute_find_similar, ComputeSpec};
use serde_json::Value;

fn fixture() -> Value {
    let p = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("service_parity.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn dsn() -> Option<String> {
    std::env::var("CINE_REC_INTEGRATION_DSN")
        .ok()
        .filter(|s| !s.is_empty())
}

const ROW_KEYS: [&str; 9] = [
    "tmdb_id", "title", "title_en", "media_type", "rating", "genres",
    "poster_path", "collection_id", "release_year",
];

#[tokio::test]
async fn service_compute_matches_python_on_frozen_seeds() {
    let Some(dsn) = dsn() else {
        if std::env::var("CINE_REC_REQUIRE_DB")
            .ok()
            .is_some_and(|v| v == "1")
        {
            panic!("CINE_REC_REQUIRE_DB=1 but no CINE_REC_INTEGRATION_DSN");
        }
        eprintln!("skipping (no CINE_REC_INTEGRATION_DSN)");
        return;
    };
    let fx = fixture();
    let db = Db::connect(&dsn).await.unwrap();

    for case in fx["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let spec: ComputeSpec =
            serde_json::from_value(case["spec"].clone()).unwrap();
        let got = compute_find_similar(&db, &spec).await.unwrap_or_else(|e| {
            panic!("case {name}: compute failed: {e}")
        });

        let want = case["results"].as_array().unwrap();
        // n>0 rule — the iron law for parity benches
        assert!(!want.is_empty(), "case {name}: fixture empty");
        assert_eq!(
            got.results.len(),
            want.len(),
            "case {name}: row count {} vs {}",
            got.results.len(),
            want.len()
        );
        // movie_ratio
        let want_ratio = case["movie_ratio"].as_f64().unwrap();
        assert!(
            (got.movie_ratio - want_ratio).abs() < 1e-12,
            "case {name}: movie_ratio {} vs {want_ratio}",
            got.movie_ratio
        );
        for (i, (g, w)) in got.results.iter().zip(want).enumerate() {
            assert_eq!(
                g.tmdb_id,
                w["tmdb_id"].as_i64().unwrap(),
                "case {name}[{i}]: tmdb_id"
            );
            for key in ROW_KEYS.iter().filter(|k| **k != "tmdb_id") {
                let g = serde_json::to_value(
                    field_of(g, key).expect("known key"),
                )
                .unwrap();
                // null-vs-missing and int-vs-float normalize through JSON
                let g = g.as_str().map(|s| Value::from(s.to_string())).unwrap_or(g);
                assert_eq!(
                    g, w[*key],
                    "case {name}[{i}].{key}: {g} vs {want}",
                    want = w[*key]
                );
            }
            let want_score = w["score"].as_f64().unwrap();
            assert!(
                (g.score - want_score).abs() <= 1e-12,
                "case {name}[{i}].score: {} vs {want_score}",
                g.score
            );
            // raw_score (pre-rounding) sanity: proves the scoring loop
            // sets it (not just copies the rounded score), and that
            // it differs by <0.001 (the rounding granularity). A naive
            // fold would produce a different raw_score; the rounded
            // score comparison above catches downstream divergence.
            assert!(
                (g.raw_score - g.score).abs() < 0.001 + 1e-15,
                "case {name}[{i}]: raw_score {raw} vs rounded {score} — not a rounding pair",
                raw = g.raw_score, score = g.score
            );
            // at least SOME results must have raw != rounded (proves
            // raw_score is genuinely pre-rounding, not a copy)
            if i == 0 {
                let any_diff = got.results.iter()
                    .any(|r| (r.raw_score - r.score).abs() > 1e-15);
                assert!(any_diff || got.results.len() == 1,
                    "case {name}: ALL raw_scores identical to rounded — suspicious");
            }
            // director_ids: SET compare — the SQL aggregates crew ids
            // via ARRAY_AGG without ORDER BY, so the ordering is
            // nondeterministic across runs (the L-6/companies
            // precedent; reviewer's flake at 9+ rows)
            let want_dirs: std::collections::HashSet<i64> =
                w["director_ids"].as_array().unwrap()
                    .iter().filter_map(|v| v.as_i64()).collect();
            let got_dirs: std::collections::HashSet<i64> =
                g.director_ids.iter().copied().collect();
            assert_eq!(
                got_dirs, want_dirs,
                "case {name}[{i}].director_ids (set)"
            );
        }
        println!("case {name}: {} rows OK", got.results.len());
    }
}

// a tiny field accessor so the JSON normalization above stays uniform
fn field_of(
    item: &cine_rec_service::similar::ScoredItemSerde,
    key: &str,
) -> Option<serde_json::Value> {
    Some(match key {
        "title" => Value::from(item.title.clone()),
        "title_en" => item.title_en.clone().map(Value::from).unwrap_or(Value::Null),
        "media_type" => Value::from(item.media_type.clone()),
        "rating" => serde_json::Number::from_f64(item.rating)
            .map(Value::Number)
            .unwrap_or(Value::Null),
        "genres" => serde_json::to_value(&item.genres).unwrap(),
        "poster_path" => {
            item.poster_path.clone().map(Value::from).unwrap_or(Value::Null)
        }
        "collection_id" => {
            item.collection_id.map(Value::from).unwrap_or(Value::Null)
        }
        "release_year" => item.release_year.map(Value::from).unwrap_or(Value::Null),
        _ => return None,
    })
}

#[tokio::test]
async fn recommend_full_matches_python_on_frozen_inputs() {
    let Some(dsn) = dsn() else {
        if std::env::var("CINE_REC_REQUIRE_DB")
            .ok()
            .is_some_and(|v| v == "1")
        {
            panic!("CINE_REC_REQUIRE_DB=1 but no CINE_REC_INTEGRATION_DSN");
        }
        eprintln!("skipping (no CINE_REC_INTEGRATION_DSN)");
        return;
    };
    let fx = fixture();
    let case = &fx["recommend_910001_full"];
    let spec: cine_rec_service::recommend::RecommendSpec =
        serde_json::from_value(case["spec"].clone()).unwrap();
    let db = Db::connect(&dsn).await.unwrap();
    let got = cine_rec_service::recommend::recommend_for_user(&db, &spec)
        .await
        .unwrap();

    // n>0
    let want = case["results"].as_array().unwrap();
    assert!(!want.is_empty());
    assert_eq!(got.results.len(), want.len(),
        "recommend: {} vs {}", got.results.len(), want.len());
    assert_eq!(got.reason, case["reason"].as_str().unwrap());
    assert_eq!(got.vector_used, case["vector_used"].as_bool().unwrap());
    // seeds: (id, mt, w-rounded-3)
    let want_seeds = case["seeds"].as_array().unwrap();
    assert_eq!(got.seeds.len(), want_seeds.len());
    for (g, w) in got.seeds.iter().zip(want_seeds) {
        assert_eq!(g.0, w[0].as_i64().unwrap(), "seed id");
        assert_eq!(g.1, w[1].as_str().unwrap(), "seed mt");
        assert!((g.2 - w[2].as_f64().unwrap()).abs() < 1e-9, "seed w");
    }
    for (i, (g, w)) in got.results.iter().zip(want).enumerate() {
        assert_eq!(g.tmdb_id, w["tmdb_id"].as_i64().unwrap(), "rec[{i}].tmdb_id");
        let gv = |key: &str| -> serde_json::Value {
            match key {
                "title" => serde_json::to_value(&g.title).unwrap(),
                "title_en" => serde_json::to_value(&g.title_en).unwrap(),
                "media_type" => serde_json::to_value(&g.media_type).unwrap(),
                "genres" => serde_json::to_value(&g.genres).unwrap(),
                "poster_path" => serde_json::to_value(&g.poster_path).unwrap(),
                "collection_id" => serde_json::to_value(g.collection_id).unwrap(),
                "release_year" => serde_json::to_value(g.release_year).unwrap(),
                _ => unreachable!(),
            }
        };
        for key in ["title", "title_en", "media_type", "genres",
                    "poster_path", "collection_id", "release_year"] {
            assert_eq!(gv(key), w[key], "rec[{i}].{key}");
        }
        assert!(
            (g.score - w["score"].as_f64().unwrap()).abs() <= 1e-12,
            "rec[{i}].score {} vs {}", g.score, w["score"]
        );
        // user_affinity: exact (None or Some(f64) at round(x,3))
        match (g.user_affinity, w["user_affinity"].as_f64()) {
            (Some(a), Some(b)) => assert!((a - b).abs() < 1e-12,
                "rec[{i}].user_affinity {a} vs {b}"),
            (None, None) => {}
            (a, b) => panic!("rec[{i}].user_affinity presence: {a:?} vs {b:?}"),
        }
        // director_ids: set compare (ARRAY_AGG unordered — see above)
        let want_dirs: std::collections::HashSet<i64> =
            w["director_ids"].as_array().unwrap()
                .iter().filter_map(|v| v.as_i64()).collect();
        let got_dirs: std::collections::HashSet<i64> =
            g.director_ids.iter().copied().collect();
        assert_eq!(got_dirs, want_dirs, "rec[{i}].director_ids (set)");
    }
    println!("recommend full: {} rows OK", got.results.len());
}
